const config = $('Resolve Config').first().json;
const supabaseUrl = config.supabaseUrl;
const supabaseKey = config.supabaseKey;

// Calculate ISO week number
const now = new Date();
const jan1 = new Date(now.getFullYear(), 0, 1);
const daysSinceJan1 = Math.floor((now.getTime() - jan1.getTime()) / 86400000);
const weekNumber = Math.ceil((daysSinceJan1 + jan1.getDay() + 1) / 7);
const year = now.getFullYear();

const dayNames = { 1: 'Mandag', 2: 'Tirsdag', 3: 'Onsdag', 4: 'Torsdag', 5: 'Fredag', 6: 'Lordag', 7: 'Sondag' };

// Fetch current week plan
let plan = null;
try {
  const plans = await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/weekly_plans?household_id=eq.default&week_number=eq.${weekNumber}&year=eq.${year}&limit=1`,
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`,
      'Content-Type': 'application/json'
    },
    json: true,
    timeout: 10000
  });
  plan = plans && plans.length > 0 ? plans[0] : null;
} catch (e) {
  // No plan found
}

let meals = [];
if (plan && plan.id) {
  try {
    meals = await this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/planned_meals?plan_id=eq.${plan.id}&order=day_of_week.asc`,
      headers: {
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`,
        'Content-Type': 'application/json'
      },
      json: true,
      timeout: 10000
    });
  } catch (e) {
    meals = [];
  }
}

const hasPlan = meals.length > 0;
let message = '';

if (hasPlan) {
  const mealLines = meals.map(m => {
    const day = dayNames[m.day_of_week] || `Dag ${m.day_of_week}`;
    const desc = m.description ? ` — ${m.description}` : '';
    return `  ${day}: *${m.name}*${desc}`;
  }).join('\n');
  message = `God morgen! Her er ukens middagsplan (uke ${weekNumber}):\n\n${mealLines}\n\nSi fra om du vil endre noe!`;
} else {
  message = `God morgen! Ingen middagsplan for uke ${weekNumber} enna. Vil du at jeg lager en? Bare si ifra sa ordner jeg det.`;
}

return [{ json: { hasPlan, weekNumber, year, message } }];

const config = $('Resolve Config').first().json;
const data = $input.first().json;

const channel = config.slackChannelHusmor || '#husmor';
const token = config.slackHusmorBotToken;

if (!token) {
  throw new Error('SLACK_HUSMOR_BOT_TOKEN is not configured');
}

const slackRes = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://slack.com/api/chat.postMessage',
  headers: {
    'Authorization': `Bearer ${token}`,
    'Content-Type': 'application/json'
  },
  body: {
    channel,
    text: data.message
  },
  json: true
});

if (!slackRes.ok) {
  throw new Error(`Slack error: ${slackRes.error}`);
}

return [{ json: { slackSent: true, ts: slackRes.ts, channel: slackRes.channel } }];
